"""Everything the customer is told, generated by code from validated data.

The model never writes a message that contains a price, a date or a commitment. The only
model-written text a customer can receive is the one follow-up question, and that question
is length-limited and goes through the same validated object.
"""

from __future__ import annotations

from riverbend.catalog import Catalog, PricedLine, format_money
from riverbend.extraction.dates import DateWindow


def ack(shop_name: str) -> str:
    return (
        f"Thanks for contacting {shop_name}. We've received your message and will get back to you shortly. "
        "You don't need to send it again."
    )


def _line(line: PricedLine, currency: str) -> str:
    qty = f" × {line.quantity}" if line.quantity > 1 else ""
    return f"• {line.name}{qty} — {format_money(line.line_total_cents, currency)}"


def work_order_summary(
    shop_name: str,
    customer_name: str,
    lines: tuple[PricedLine, ...],
    total_cents: int,
    window: DateWindow | None,
    currency: str,
) -> str:
    hello = f"Hi {customer_name}, thanks" if customer_name else "Thanks"
    parts = [f"{hello} for contacting {shop_name}. Here's what we've noted:"]
    parts += [_line(line, currency) for line in lines]
    parts.append(f"Estimated total: {format_money(total_cents, currency)}.")
    if any(line.requires_inspection for line in lines):
        parts.append("Items marked for inspection are confirmed once we've seen the bike.")
    if window:
        parts.append(f"Requested: {window.label}.")
    parts.append("A team member will confirm your appointment shortly.")
    return "\n".join(parts)


def price_quote(shop_name: str, lines: tuple[PricedLine, ...], catalog: Catalog) -> str:
    parts = [f"Thanks for asking! Current prices at {shop_name}:"]
    for line in lines:
        svc = catalog.services[line.code]
        parts.append(
            f"• {svc.name} — {format_money(svc.price_cents, catalog.currency)} (about {svc.minutes} minutes)"
        )
    parts.append("Reply to this message with a day that suits you if you'd like to book.")
    return "\n".join(parts)


def follow_up(question: str) -> str:
    return f"{question}\n\n(Just reply to this message — we'll pick up where we left off.)"


def handoff(shop_name: str) -> str:
    return (
        f"Thanks for your message. We've passed it to the team at {shop_name}, "
        "and a member of staff will reply to you personally."
    )


def cancellation_ack(shop_name: str) -> str:
    return f"Thanks for letting us know. We've passed your cancellation to the team at {shop_name}."


def redirect(shop_name: str, other_shop_name: str, other_contact: str) -> str:
    contact = f" at {other_contact}" if other_contact else ""
    return (
        f"No problem. {shop_name} won't act on this request. Please contact {other_shop_name}{contact} directly — "
        "for your privacy we don't forward messages between shops."
    )
